let catalog=PRODUCTS;let selectedProduct=null;
const grid=document.getElementById('product-grid'),tree=document.getElementById('category-tree'),search=document.getElementById('product-search'),dialog=document.getElementById('product-dialog');let selected='全部商品';
function categoryButton(label,group=false){const b=document.createElement('button');b.type='button';b.className='category-button '+(group?'group-title':'subcategory');b.textContent=label;b.setAttribute('aria-pressed',label===selected);b.addEventListener('click',()=>{selected=label;tree.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x.textContent===label));render()});return b}function renderCategories(){tree.replaceChildren();tree.append(categoryButton('全部商品',true));[...new Set(catalog.map(p=>p.group))].forEach(group=>{const div=document.createElement('div');div.className='category-group';div.append(categoryButton(group,true));catalog.filter(p=>p.group===group).forEach(p=>div.append(categoryButton(p.category)));tree.append(div)});}renderCategories();
function showProduct(p){selectedProduct=p;document.getElementById('dialog-title').textContent=p.name;document.getElementById('dialog-category').textContent=p.group+' / '+p.category;const img=document.getElementById('dialog-image');img.src=p.image;img.alt=p.name+' AI 商品示意';document.getElementById('dialog-description').textContent=p.description;document.getElementById('fitment-note').textContent=p.group==='改裝部品'?'改裝部品需確認車種、年式、安裝尺寸與使用條件；示意圖不代表相容任何車款。':'正式商品的尺寸、規格與使用條件將於上架時提供。';dialog.querySelector('.product-price').firstChild.textContent='NT$'+p.price.toLocaleString('zh-TW')+' ';dialog.showModal()}
function render(){const q=search.value.trim().toLowerCase();const found=catalog.filter(p=>(selected==='全部商品'||p.group===selected||p.category===selected)&&[p.name,p.group,p.category].join(' ').toLowerCase().includes(q));grid.replaceChildren();found.forEach(p=>{const card=document.createElement('article');card.className='product-card';const imageButton=document.createElement('button');imageButton.type='button';imageButton.className='product-image-button';imageButton.setAttribute('aria-label','查看'+p.name);const img=document.createElement('img');img.src=p.image;img.alt=p.name+' AI 示意圖';img.loading='lazy';img.width=512;img.height=512;const label=document.createElement('span');label.className='ai-label';label.textContent='AI 示意';imageButton.append(img,label);imageButton.addEventListener('click',()=>showProduct(p));const category=document.createElement('p');category.className='product-category';category.textContent=p.group+' / '+p.category;const title=document.createElement('h3');title.textContent=p.name;const price=document.createElement('p');price.className='product-price';price.append('NT$'+p.price.toLocaleString('zh-TW')+' ');const note=document.createElement('small');note.textContent='展示價格';price.append(note);const detail=document.createElement('button');detail.type='button';detail.className='product-detail';detail.textContent='查看商品 ↗';detail.addEventListener('click',()=>showProduct(p));const add=document.createElement('button');add.type='button';add.className='product-detail';add.textContent='加入購物車 ＋';add.onclick=async()=>{add.disabled=true;try{await WildRideShop.add(p.id);add.textContent='已加入 ✓'}catch(e){alert(e.message)}finally{add.disabled=false}};card.append(imageButton,category,title,price,detail,add);grid.append(card)});document.getElementById('product-count').textContent=found.length+' 件商品';document.getElementById('active-category').textContent=selected;document.getElementById('empty-state').hidden=found.length!==0}search.addEventListener('input',render);document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'關閉 ×':'選單 ＋'});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='選單 ＋'}});render();

document.getElementById("dialog-add").onclick=async e=>{e.target.disabled=true;try{await WildRideShop.add(selectedProduct.id);document.getElementById("shop-feedback").textContent="已加入購物車，可繼續挑選或前往購物車。"}catch(err){document.getElementById("shop-feedback").textContent=err.message}finally{e.target.disabled=false}};WildRideShop.init().then(()=>WildRideMember.request("catalog")).then(r=>{catalog=r.products;renderCategories();render()}).catch(()=>{document.querySelector(".shop-notice span").textContent="會員服務尚未連線，目前僅供商品瀏覽。請啟動本機會員服務。"});
